dService("19B10000-E8F2-537E-4F6C-D104768A1214"); // Bluetooth\xae Low Energy LED Service\n\n// Bluetooth\xae Low Energy LED Switch Characteristic - custom 128-bit UUID, read and writable by central\nBLEByteCharacteristic switchCharacteristic("19B10001-E8F2-537E-4F6C-D104768A1214", BLERead | BLEWrite);\n\nconst int ledPin = LED_BUILTIN; // pin to use for the LED\n\nvoid setup() {\n  Serial.begin(9600);\n  while (!Serial);\n\n  // set LED pin to output mode\n  pinMode(ledPin, OUTPUT);\n\n  // begin initialization\n  if (!BLE.begin()) {\n    Serial.println("starting Bluetooth\xae Low Energy module failed!");\n\n    while (1);\n  }\n\n  // set advertised local name and service UUID:\n  BLE.setLocalName("XIAO");\n  BLE.setAdvertisedService(ledService);\n\n  // add the characteristic to the service\n  ledService.addCharacteristic(switchCharacteristic);\n\n  // add service\n  BLE.addService(ledService);\n\n  // set the initial value for the characeristic:\n  switchCharacteristic.writeValue(0);\n\n  // start advertising\n  BLE.advertise();\n\n  // print address\n  Serial.print("Address: ");\n  Serial.println(BLE.address());\n\n  Serial.println("XIAO nRF52840 Peripheral");\n}\n\nvoid loop() {\n  // listen for Bluetooth\xae Low Energy peripherals to connect:\n  BLEDevice central = BLE.central();\n\n  // if a central is connected to peripheral:\n  if (central) {\n    Serial.print("Connected to central: ");\n    // print the central\'s MAC address:\n    Serial.println(central.address());\n\n    // while the central is still connected to peripheral:\n    while (central.connected()) {\n      // if the remote device wrote to the characteristic,\n      // use the value to control the LED:\n      if (switchCharacteristic.written()) {\n        if (switchCharacteristic.value()) {   // any value other than 0\n          Serial.println("LED on");\n          digitalWrite(ledPin, HIGH);         // will turn the LED on\n        } else {                              // a 0 value\n          Serial.println(F("LED off"));\n          digitalWrite(ledPin, LOW);          // will turn the LED off\n        }\n      }\n    }\n\n    // when the central disconnects, print it out:\n    Serial.print(F("Disconnected from central: "));\n    Serial.println(central.address());\n  }\n}\n'})}),"\n",(0,r.jsx)(n.p,{children:'\u8FD9\u4E2A\u7A0B\u5E8F\u7684\u4E3B\u8981\u76EE\u7684\u662F\u8BA9 XIAO \u6210\u4E3A\u4E00\u4E2A\u540D\u4E3A"XIAO"\u7684\u84DD\u7259\u8BBE\u5907\uFF0C\u53EF\u4EE5\u88AB\u5176\u4ED6\u84DD\u7259\u8BBE\u5907\u641C\u7D22\u548C\u8FDE\u63A5\u3002\u8FDE\u63A5\u540E\uFF0C\u60A8\u53EF\u4EE5\u901A\u8FC7\u53D1\u9001 0 \u6216 1 \u6765\u63A7\u5236 XIAO \u4E0A\u7684 LED\uFF0C\u5206\u522B\u7528\u4E8E\u5173\u95ED\u6216\u6253\u5F00\u5B83\u4EEC\u3002'}),"\n",(0,r.jsx)(n.p,{children:"\u5C06 Seeed Studio XIAO nRF52840 \u653E\u5728\u6269\u5C55\u677F\u4E0A\u3002"}),"\n",(0,r.jsx)("div",{align:"center",children:(0,r.jsx)("img",{width:400,src:"https://files.seeedstudio.com/wiki/Seeeduino-XIAO-Expansion-Board/XIAO-to-board.png"})}),"\n",(0,r.jsx)(n.p,{children:"\u4E3A\u6B64\uFF0C\u8FDE\u63A5\u4E86\u6269\u5C55\u677F\u7684 XIAO \u9700\u8981\u4E0A\u4F20\u4EE5\u4E0B\u7A0B\u5E8F\u3002"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:'#include <ArduinoBLE.h>\n#include <U8x8lib.h>\n#include <Wire.h>\n\n// variables for button\nconst int buttonPin = D1;\nint oldButtonState = LOW;\n\nvoid setup() {\n  Serial.begin(9600);\n  while (!Serial);\n\n  // configure the button pin as input\n  pinMode(buttonPin, INPUT_PULLUP);\n\n  // initialize the Bluetooth\xae Low Energy hardware\n  BLE.begin();\n\n  Serial.println("Bluetooth\xae Low Energy Central - LED control");\n\n  // start scanning for peripherals\n  BLE.scanForName("XIAO");\n}\n\nvoid loop() {\n  // check if a peripheral has been discovered\n  BLEDevice peripheral = BLE.available();\n  if (peripheral) {\n    // discovered a peripheral, print out address, local name, and advertised service\n    Serial.print("Found ");\n    Serial.print(peripheral.address());\n    Serial.print(" \'");\n    Serial.print(peripheral.localName());\n    Serial.print("\' ");\n    Serial.print(peripheral.advertisedServiceUuid());\n    Serial.println();\n\n    if (peripheral.localName() != "XIAO") {\n      return;\n    }\n\n    // stop scanning\n    BLE.stopScan();\n\n    system_control(peripheral);\n\n    // peripheral disconnected, start scanning again\n    BLE.scanForName("XIAO");\n  }\n  delay(100);\n}\n\nvoid system_control(BLEDevice peripheral) {\n  // connect to the peripheral\n  Serial.println("Connecting ...");\n\n  if (peripheral.connect()) {\n    Serial.println("Connected");\n  } else {\n    Serial.println("Failed to connect!");\n    return;\n  }\n\n  // discover peripheral attributes\n  Serial.println("Discovering attributes ...");\n  if (peripheral.discoverAttributes()) {\n    Serial.println("Attributes discovered");\n  } else {\n    Serial.println("Attribute discovery failed!");\n    peripheral.disconnect();\n    return;\n  }\n\n  // retrieve the LED characteristic\n  BLECharacteristic ledCharacteristic = peripheral.characteristic("19b10001-e8f2-537e-4f6c-d104768a1214");\n\n  if (!ledCharacteristic) {\n    Serial.println("Peripheral does not have LED characteristic!");\n    peripheral.disconnect();\n    return;\n  } else if (!ledCharacteristic.canWrite()) {\n    Serial.println("Peripheral does not have a writable LED characteristic!");\n    peripheral.disconnect();\n    return;\n  }\n\n  while (peripheral.connected()) {\n    // while the peripheral is connected\n    // read the button pin\n    int buttonState = digitalRead(buttonPin);\n\n    if (oldButtonState != buttonState) {\n      // button changed\n      oldButtonState = buttonState;\n\n      if (buttonState) {\n        Serial.println("button pressed");\n\n        // button is pressed, write 0x01 to turn the LED on\n        ledCharacteristic.writeValue((byte)0x01);\n      } else {\n        Serial.println("button released");\n\n        // button is released, write 0x00 to turn the LED off\n        ledCharacteristic.writeValue((byte)0x00);\n      }\n    }\n  }\n\n  Serial.println("Peripheral disconnected");\n}\n'})}),"\n",(0,r.jsx)(n.p,{children:'\u4E00\u65E6\u60A8\u4E0A\u4F20\u4E86\u7A0B\u5E8F\uFF0C\u6253\u5F00\u4E32\u53E3\u76D1\u89C6\u5668\uFF0C\u7A0B\u5E8F\u5C06\u5F00\u59CB\u641C\u7D22\u9644\u8FD1\u672C\u5730\u540D\u79F0\u4E3A"XIAO"\u7684\u84DD\u7259\u8BBE\u5907\u5E76\u8FDE\u63A5\u5230\u5B83\uFF08\u60A8\u9700\u8981\u7B49\u5F851\u52303\u5206\u949F\uFF09\u3002'}),"\n",(0,r.jsx)(n.p,{children:"\u4E00\u65E6\u4E32\u53E3\u76D1\u89C6\u5668\u4E2D\u663E\u793A\u6210\u529F\u8FDE\u63A5\u6D88\u606F\uFF0C\u60A8\u5C31\u53EF\u4EE5\u901A\u8FC7\u6269\u5C55\u677F\u7684\u6309\u952ED1\u63A7\u5236\u53E6\u4E00\u4E2AXIAO nRF52840 LED\u7684\u5F00\u5173\u3002"}),"\n",(0,r.jsx)(n.p,{children:"\u5F53\u7136\uFF0C\u5982\u679C\u60A8\u6CA1\u6709\u6269\u5C55\u677F\uFF0C\u60A8\u4E5F\u53EF\u4EE5\u4F7F\u7528\u81EA\u5DF1\u7684\u6309\u94AE\u6216\u5176\u4ED6\u8BBE\u5907\u3002"}),"\n",(0,r.jsx)(n.h2,{id:"\u66F4\u591A\u5185\u5BB9",children:"\u66F4\u591A\u5185\u5BB9\uFF1F"}),"\n",(0,r.jsxs)(n.p,{children:["\u5982\u679C\u60A8\u60F3\u5C1D\u8BD5\u66F4\u591A\u793A\u4F8B\uFF0C\u53EF\u4EE5\u5BFC\u822A\u5230 ",(0,r.jsx)(n.code,{children:"File > Examples > INCOMPATIBLE > ArduinoBLE"})," \u5E76\u67E5\u770B ",(0,r.jsx)(n.strong,{children:"ArduinoBLE"})," \u4E0B\u7684\u6240\u6709\u793A\u4F8B"]}),"\n",(0,r.jsx)(n.h2,{id:"\u6280\u672F\u652F\u6301\u4E0E\u4EA7\u54C1\u8BA8\u8BBA",children:"\u6280\u672F\u652F\u6301\u4E0E\u4EA7\u54C1\u8BA8\u8BBA"}),"\n",(0,r.jsx)(n.p,{children:"\u611F\u8C22\u60A8\u9009\u62E9\u6211\u4EEC\u7684\u4EA7\u54C1\uFF01\u6211\u4EEC\u5728\u8FD9\u91CC\u4E3A\u60A8\u63D0\u4F9B\u4E0D\u540C\u7684\u652F\u6301\uFF0C\u4EE5\u786E\u4FDD\u60A8\u4F7F\u7528\u6211\u4EEC\u4EA7\u54C1\u7684\u4F53\u9A8C\u5C3D\u53EF\u80FD\u987A\u7545\u3002\u6211\u4EEC\u63D0\u4F9B\u591A\u79CD\u6C9F\u901A\u6E20\u9053\uFF0C\u4EE5\u6EE1\u8DB3\u4E0D\u5